function renderBatchSubs(){const m=currentMatch(),by=Object.fromEntries(loadPlayers().map(p=>[p.id,p]));$('subOffList').innerHTML=m.currentOnPitch.map(id=>by[id]).filter(Boolean).map(p=>`<label class="batch-choice"><input type="checkbox" class="batch-off-check" data-id="${p.id}" ${batchOffIds.has(p.id)?'checked':''}><span>${escapeHtml(playerLabel(p))}</span></label>`).join('');$('subOnList').innerHTML=m.currentSubs.map(id=>by[id]).filter(Boolean).map(p=>`<label class="batch-choice"><input type="checkbox" class="batch-on-check" data-id="${p.id}" ${batchOnIds.has(p.id)?'checked':''}><span>${escapeHtml(playerLabel(p))}</span></label>`).join('');$('subOffCount').textContent=batchOffIds.size;$('subOnCount').textContent=batchOnIds.size;const valid=batchOffIds.size>0&&batchOffIds.size===batchOnIds.size;$('saveBatchSubsBtn').disabled=!valid;$('saveBatchSubsBtn').textContent=valid?`Save ${batchOffIds.size} substitution${batchOffIds.size===1?'':'s'}`:'Save substitutions';document.querySelectorAll('.batch-off-check').forEach(c=>c.onchange=()=>{c.checked?batchOffIds.add(c.dataset.id):batchOffIds.delete(c.dataset.id);renderBatchSubs()});document.querySelectorAll('.batch-on-check').forEach(c=>c.onchange=()=>{c.checked?batchOnIds.add(c.dataset.id):batchOnIds.delete(c.dataset.id);renderBatchSubs()})}
function saveBatchSubs(){const m=currentMatch();if(!m||!batchOffIds.size||batchOffIds.size!==batchOnIds.size)return;const before=eventState(m),offs=[...batchOffIds],ons=[...batchOnIds],sec=elapsedNow(),min=matchMinute();offs.forEach((off,i)=>{const on=ons[i];const ev={id:makeId(),type:'substitution',period:m.period,seconds:sec,minute:min,offId:off,onId:on,beforeState:eventState(m)};m.currentOnPitch=m.currentOnPitch.filter(id=>id!==off);m.currentOnPitch.push(on);m.currentSubs=m.currentSubs.filter(id=>id!==on);m.currentSubs.push(off);m.events.push(ev)});saveCurrent(m);$('subDialog').close();renderLive()}
